<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,errorText} from '../api/client'
import {items} from '../api'
import OperationForm from './OperationForm.vue'
import RecordView from './RecordView.vue'
import PublicInquiry from './PublicInquiry.vue'
const props=defineProps<{mode:'projects'|'events';projectId?:string}>()
const rows=ref<any[]>([]),detail=ref<any>(null),busy=ref(false),error=ref(''),page=ref(1),total=ref(0),inquiry=ref(false),register=ref(false),cancel=ref<any>(null),receipts=ref<any[]>([])
try{receipts.value=JSON.parse(sessionStorage.getItem('yue-event-receipts')||'[]')}catch{}
async function load(){busy.value=true;error.value='';try{const r=await api.get('/public/'+props.mode,{page:page.value,page_size:8});rows.value=items(r);total.value=r.total??rows.value.length;if(props.projectId)await view(rows.value.find(r=>r.id===props.projectId)||{id:props.projectId})}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function view(row:any){error.value='';try{detail.value=await api.get('/public/'+props.mode+'/'+encodeURIComponent(row.id));inquiry.value=false}catch(e){error.value=errorText(e)}}
function registered(r:any){receipts.value.unshift({registrationId:r.registrationId,eventId:r.eventId,title:detail.value?.title,version:r.version,status:r.status,cancelToken:r.cancelToken});sessionStorage.setItem('yue-event-receipts',JSON.stringify(receipts.value));load()}
function cancelled(){if(cancel.value){receipts.value=receipts.value.map(r=>r.registrationId===cancel.value.registrationId?{...r,status:'CANCELLED'}:r);sessionStorage.setItem('yue-event-receipts',JSON.stringify(receipts.value));load()}}
onMounted(load)
</script>
<template><section class="live-public-services"><div class="visitor-section-title"><div><span class="eyebrow">{{mode==='projects'?'CURRENT PROGRAMMES':'UPCOMING EVENTS'}}</span><h2>{{mode==='projects'?'当前开放项目':'活动与报名'}}</h2><p>{{mode==='projects'?'了解当前公布的培养项目，详情及咨询以实际项目资料为准。':'查看实际活动安排和剩余名额，报名须由本人核对确认。'}}</p></div></div><p v-if="error" class="error-callout" role="alert">{{error}}</p><p v-if="busy" class="muted">正在加载…</p><div class="visitor-policy-grid"><article v-for="r in rows" :key="r.id" class="visitor-policy-card"><h3>{{r.name||r.title}}</h3><p>{{r.description}}</p><p v-if="mode==='events'">{{r.startAt?.replace('T',' ').slice(0,16)}} · {{r.location}} · 剩余 {{r.remainingCapacity}} 名</p><button class="btn outline" @click="view(r)">了解详情 →</button></article></div><p v-if="!busy&&!rows.length" class="muted">{{mode==='events'?'具体活动安排将另行公布，欢迎浏览项目资料。':'当前暂无已公布项目，您仍可浏览下方项目资料导览。'}}</p><div v-if="total>8" class="public-pagination"><button class="btn outline" :disabled="page===1" @click="page--;load()">上一页</button><span>第 {{page}} 页</span><button class="btn outline" :disabled="page*8>=total" @click="page++;load()">下一页</button></div><article v-if="detail" class="visitor-paper public-live-detail"><div class="panel-title"><h2>{{detail.name||detail.title}}</h2><button class="text-link" @click="detail=null">收起</button></div><RecordView :value="detail"/><button v-if="mode==='projects'" class="btn primary" @click="inquiry=!inquiry">咨询项目详情</button><button v-else class="btn primary" :disabled="detail.status!=='OPEN'||detail.remainingCapacity<=0" @click="register=true">核对并报名活动</button><PublicInquiry v-if="inquiry" :suggested-name="detail.name"/></article><section v-if="mode==='events'&&receipts.length" class="visitor-paper"><h3>本次访问的报名回执</h3><article v-for="r in receipts" :key="r.registrationId"><p>{{r.title}} · {{r.status==='CANCELLED'?'已取消':'已报名'}}</p><small>回执：{{r.registrationId}}</small><button v-if="r.status!=='CANCELLED'&&r.cancelToken" class="text-link" @click="cancel=r">取消这次报名</button></article></section><OperationForm v-if="register&&detail" path="/api/v1/events/{event_id}/registrations" method="POST" title="活动报名" :params="{event_id:detail.id}" @close="register=false" @saved="registered"/><OperationForm v-if="cancel" path="/api/v1/registrations/{registration_id}/cancel" method="POST" title="取消活动报名" :params="{registration_id:cancel.registrationId}" :record="cancel" :preset="{cancel_token:cancel.cancelToken}" @close="cancel=null" @saved="cancelled"/></section></template>
